140	    public List<List<Animal>> getAnimalsPerBlock()
141	    {
142	        List<List<Animal>> blocks = new ArrayList<>();
143	        for(int colStart = 0 ; colStart < width; colStart += DISEASE_BLOCK_SIZE){
144	            for (int rowStart = 0; rowStart < depth; rowStart += DISEASE_BLOCK_SIZE) {
145	                List<Animal> blockAnimals = new ArrayList<>();
146	                int colEnd = Math.min(colStart + DISEASE_BLOCK_SIZE, width);
147	                int rowEnd = Math.min(rowStart + DISEASE_BLOCK_SIZE, depth);
148	                for (int col = colStart; col < colEnd; col++) {
149	                    for(int row = rowStart; row < rowEnd; row++) {
150	                        Animal animal = getAnimalAt(row, col);
151	                        if(animal != null) {
152	                            blockAnimals.add(animal);
153	                        }
154	                    }
155	                }
156	                blocks.add(blockAnimals);
157	            }
158	        }
159	        return blocks;
