27	    public HerbivoreAnimal(boolean randomAge,Field field, Location location, Gender gender, int baseLevel, int maxAge)
28	    {
29	        super(randomAge, field, location, gender, baseLevel, maxAge);
30	    }
31	
32	    protected abstract int getMaxAge();
33	
34	    protected abstract int getBreedingAge();
35	
36	    protected abstract double getBreedingProbability(Weather weather);
37	
38	    protected abstract int getMaxLitterSize();
39	
40	    protected abstract Set<PlantSpecies> getTargetPlants();
41	
42	    @Override
43	    public final void act(List<Actor> newAnimals, Weather weather, DayState dayState)
44	    {
45	        incrementAge(getMaxAge());
46	        incrementHunger();
47	        if(!isAlive()) {
48	            return;
49	        }
50	        meet(newAnimals, getMaxLitterSize(), getBreedingProbability(weather), getBreedingAge());
51	        Location newLocation = findFood(getTargetPlants());
52	        if(newLocation == null) {
53	            newLocation = getField().freeAdjacentLocation(getLocation());
54	        }
55	        if(newLocation != null) {
56	            setLocation(newLocation);
57	        }
58	        else {
59	            setDead();
60	        }
61	    }
62	    
63	    /**
64	     * Seek for the food in adjacent locations that are of type of plant
65	     * @param targetPlants the preferred diet of the animal (e.g eats only grass)
66	     * @return the location traveled to in order to access the food
67	     */
68	    public Location findFood(Set<PlantSpecies> targetPlants) 
69	    {
70	        Field field = getField();
71	        Iterator<Location> it = field.adjacentLocations(getLocation()).iterator();
72	        while(it.hasNext()) {
73	            Location where = it.next();
74	            Plant plant = field.getPlantAt(where);
75	            if(plant != null && targetPlants.contains(plant.getSpecies())) {
76	                if(plant.isAlive()) {
77	                    this.foodLevel += plant.getFeedingValue();
78	                    plant.setDead();
79	                    return where;
80	                }
81	            }
82	        }
83	        return null;
84	    }
85	}

