113	     * @param breedingProbability the likelyhood of giving birth.
114	     * @param breedingAge the minimum age to be able to breed.
115	     */
116	    protected void meet(List<Actor> newAnimals,int maxLitter, double breedingProbability, int breedingAge)
117	    {
118	        List<Location> adjacent = field.adjacentLocations(getLocation());
119	        Iterator<Location> it = adjacent.iterator();
120	        while(it.hasNext()) {
121	            Location where = it.next();
122	            Animal animal = field.getAnimalAt(where);
123	            if(animal == null || animal.getSpecies() != getSpecies()) {
124	                continue;
125	            }
126	            if(animal.getGender() == this.getGender()) {
127	                continue;
128	            }
129	            int births = breed(maxLitter, breedingProbability, breedingAge);
130	            giveBirth(newAnimals, births);
131	        }
132	    }
