134	    /**
135	     * Returns the amount of animals to breed.
136	     * 
137	     * @param maxLitter the maximum amount of animals that the animal can breed.
138	     * @param breedingProbability indicates the likelyhood of breeding.
139	     * @param breedingAge The minimum age to be able to breed.
140	     * @return an integer representing the amount of animals to give birth.
141	     */
142	    private int breed(int maxLitter, double breedingProbability, int breedingAge)
143	    {
144	        int births = 0;
145	        if(age >= breedingAge){
146	            double randomValue = rand.nextDouble();
147	            if(randomValue <= breedingProbability) {
148	                births = rand.nextInt(maxLitter) + 1;
149	            }
150	        }
151	        return births;
152	    }
