154	    /**
155	     * Gives birth to animal by appending the animals to the input list.
156	     * 
157	     * @param newAnimals list of the new born animals.
158	     * @param births number of animals to give birth.
159	     */
160	    private void giveBirth(List<Actor> newAnimals, int births)
161	    {
162	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
163	        for (int i = 0; i < births && free.size() > 0; i++) {
164	            Location loc = free.remove(0);
165	            Gender randomGender = Utils.getRandomEnumValue(Gender.class);
166	            Animal newBorn = getSpecies().createYoung(field, loc, randomGender);
167	            newAnimals.add(newBorn);
168	        }
169	    }
